<script setup lang="ts">
import { computed, ref, onMounted, onBeforeUnmount, watch } from 'vue'
import ChartTooltip from './ChartTooltip.vue'
const props=withDefaults(defineProps<{labels:string[]; values:number[]; unit?:string; bars?:boolean; valueLabel?:string; integer?:boolean; showValues?:boolean; selectedIndex?:number; tooltipLabels?:string[]; tooltipDetails?:string[][]; series?:{name:string;color:string;values:number[]}[]}>(),{unit:'',bars:false})
const emit=defineEmits<{select:[index:number]}>()
const canvas=ref<SVGSVGElement>(),width=ref(620);let observer:ResizeObserver
onMounted(()=>{observer=new ResizeObserver(entries=>width.value=entries[0].contentRect.width);observer.observe(canvas.value!)})
onBeforeUnmount(()=>observer.disconnect())
const rawMax=computed(()=>Math.max(1,...props.values,...(props.series||[]).flatMap(s=>s.values)))
const tickCount=computed(()=>props.integer?Math.min(4,Math.ceil(rawMax.value)):4)
const max=computed(()=>props.integer?Math.ceil(rawMax.value/tickCount.value)*tickCount.value:rawMax.value)
const ticks=computed(()=>Array.from({length:tickCount.value+1},(_,i)=>max.value*i/tickCount.value))
const x=(i:number)=>35+(i+.5)*(width.value-60)/Math.max(1,props.labels.length),y=(v:number)=>180-v/max.value*145
const line=computed(()=>props.values.map((v,i)=>`${x(i)},${y(v)}`).join(' '))
const hover=ref<{index:number;x:number;y:number}|null>(null)
const tooltipLines=computed(()=>{if(!hover.value)return [];const i=hover.value.index;return [...(props.series?props.series.map(s=>`${s.name}：${s.values[i]} ${props.unit}`):[`${props.valueLabel||'记录值'}：${props.values[i]} ${props.unit}`]),...(props.tooltipDetails?.[i]||[])]})
function show(index:number,event:PointerEvent){hover.value={index,x:event.clientX,y:event.clientY}}
function focus(index:number,event:FocusEvent){const r=(event.currentTarget as SVGElement).getBoundingClientRect();hover.value={index,x:r.left+r.width/2,y:r.top+20}}
watch(()=>[props.labels,props.values,props.series],()=>hover.value=null)
</script>
<template><svg class="fit-chart" :viewBox="'0 0 '+width+' 225'" ref="canvas" @pointerleave="hover=null" preserveAspectRatio="none" role="img" :aria-label="'历史趋势，单位'+unit"><g v-for="tick in ticks" :key="tick"><line x1="35" :x2="width-25" :y1="y(tick)" :y2="y(tick)" stroke="var(--line)"/><text x="15" :y="y(tick)+4" text-anchor="end">{{ integer?tick:tick.toFixed(max>10?0:1) }}</text></g><text x="15" y="20">{{ unit }}</text><template v-if="series"><g v-for="(s,j) in series" :key="s.name"><rect v-for="(v,i) in s.values" :key="i" :x="x(i)-25+j*17" :y="y(v)" width="14" :height="180-y(v)" rx="4" :fill="s.color"><title>{{ labels[i] }} · {{ s.name }} {{ v }}{{ unit }}</title></rect></g></template><template v-else-if="bars"><rect v-for="(v,i) in values" :key="i" :x="x(i)-12" :y="y(v)" width="24" :height="180-y(v)" rx="5" fill="#53bc99"><title>{{ labels[i] }} · {{ v }}{{ unit }}</title></rect></template><template v-else-if="values.length"><polygon :points="`${x(0)},180 ${line} ${x(values.length-1)},180`" fill="#42bc9620"/><polyline :points="line" fill="none" stroke="#219e77" stroke-width="3"/><g v-for="(v,i) in values" :key="i"><circle :cx="x(i)" :cy="y(v)" r="5" fill="#199d77"/><text :x="x(i)" :y="y(v)-12" text-anchor="middle">{{ Number(v.toFixed(1)) }}</text><title>{{ labels[i] }} · {{ v }}{{ unit }}</title></g></template><g v-if="showValues" pointer-events="none"><text v-for="(v,i) in values" :key="i" :x="x(i)" :y="y(v)-9" text-anchor="middle">{{ v }}{{ unit }}</text></g><rect v-if="selectedIndex!==undefined&&labels[selectedIndex]!==undefined" :x="35+selectedIndex*(width-60)/labels.length" y="25" :width="(width-60)/labels.length" height="160" rx="5" fill="#219e77" fill-opacity=".05" pointer-events="none"/><text v-for="(label,i) in labels" :key="i" :x="x(i)" y="210" text-anchor="middle">{{ label }}</text><text v-if="!values.length&&!series" :x="width/2" y="100" text-anchor="middle">暂无记录，补录后将在这里显示趋势</text><g v-if="hover" pointer-events="none"><line :x1="x(hover.index)" :x2="x(hover.index)" y1="28" y2="180" stroke="#7cae9e" stroke-dasharray="4 4"/><circle v-if="!bars&&!series" :cx="x(hover.index)" :cy="y(values[hover.index])" r="8" fill="#199d77" fill-opacity=".3"/></g><rect v-for="(label,i) in labels" :key="'hover-'+i" :x="35+i*(width-60)/labels.length" y="25" :width="(width-60)/labels.length" height="160" fill="transparent" tabindex="0" :aria-label="(tooltipLabels?.[i]||label)+'，'+(series?series.map(s=>s.name+' '+s.values[i]+' '+unit).join('，'):values[i]+' '+unit)" @pointermove="show(i,$event)" @click="emit('select',i)" @keydown.enter.prevent="emit('select',i)" @keydown.space.prevent="emit('select',i)" @focus="focus(i,$event)" @blur="hover=null" @keydown.esc="hover=null"/></svg><ChartTooltip v-if="hover" :x="hover.x" :y="hover.y" :label="tooltipLabels?.[hover.index]||labels[hover.index]" :lines="tooltipLines"/></template>
